/* Verifies the compulsory-miss-rate model from the CENG331 "Miss Rate
 * Analysis for Matrix Multiply" slides: block = 32B (four doubles), N
 * large, cache too small to hold more than one row, so only same-block
 * reuse ever hits (1/N -> 0). */
#include <stdio.h>

#define N 64      /* matrix dimension       */
#define ELEM 8     /* sizeof(double)          */
#define BLOCK 32    /* bytes per cache block   */

/* 'prev_block' models a cache that remembers only the single most
 * recently touched block, matching the 1/N -> 0 assumption. */
static double trial(int row_major) {
    long prev_block = -1, hits = 0, total = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            long addr = row_major ? (long)(i * N + j) * ELEM
                                   : (long)(j * N + i) * ELEM;
            long block = addr / BLOCK;
            if (block == prev_block) hits++;
            prev_block = block;
            total++;
        }
    }
    return 1.0 - (double) hits / total;
}

int main(void) {
    double stride1 = trial(1), strideN = trial(0);
    printf("row-major    (stride 1): miss rate = %.4f (predicted %.4f)\n",
           stride1, (double) ELEM / BLOCK);
    printf("column-major (stride N): miss rate = %.4f (predicted %.4f)\n",
           strideN, 1.0);
    return 0;
}
